use super::super::{
    BsimSoiBodyMode, K_OVER_Q, PreparedBsimSoiSetup, PreparedBsimSoiTemperature, binned, integer,
    positive, real,
};
use super::{BsimSoiChannelBias, BsimSoiDrainChannelPoint, Jet, PreparedBsimSoiDrainChannel};
use crate::ModelError;

/// Heat generated by channel conduction, the thermal residual and stored energy.
/// Values use W, W and J; derivatives use the five physical channel coordinates.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BsimSoiHeatPoint {
    pub generated: Jet,
    pub residual: Jet,
    pub energy: Jet,
}

/// Parasitic branch conductances including instance multiplicity.
///
/// A zero coefficient denotes an absent branch, not an additional short.
/// The gate electrode joins external gate to gate prime (mode 1), or
/// external gate to midgate (mode 3). The relaxation branch joins external
/// gate (mode 2) or midgate (mode 3) to gate prime.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct BsimSoiParasiticPoint {
    pub gate_electrode: f64,
    pub gate_relaxation: Jet,
    pub body_contact: f64,
    pub drain_body: f64,
    pub source_body: f64,
    pub heat: BsimSoiHeatPoint,
}

#[derive(Clone, Copy, Debug, PartialEq)]
struct GateLaw {
    mode: i32,
    electrode: f64,
    xrcrg1: f64,
    beta_scale: f64,
}

impl GateLaw {
    fn relaxation(self, channel: &BsimSoiDrainChannelPoint) -> Jet {
        if self.mode <= 1 {
            return Jet::constant(0.);
        }
        let conductance =
            self.xrcrg1 * (self.beta_scale * channel.beta + channel.output_conductance_ratio);
        if self.mode == 2 {
            self.electrode * conductance / (self.electrode + conductance)
        } else {
            conductance
        }
    }
}

/// Immutable parasitic and active thermal laws.
#[derive(Clone, Copy, Debug, PartialEq)]
pub struct PreparedBsimSoiParasitics {
    drain: PreparedBsimSoiDrainChannel,
    temperature: PreparedBsimSoiTemperature,
    gate: GateLaw,
    body_contact: f64,
    body_contact_noise: f64,
    drain_body: f64,
    source_body: f64,
}

impl PreparedBsimSoiParasitics {
    pub(super) fn gate_noise_conductance(&self, point: &BsimSoiParasiticPoint) -> f64 {
        match self.gate.mode {
            1 | 3 => self.gate.electrode,
            2 => {
                self.gate.electrode
                    / (1. + self.gate.electrode / point.gate_relaxation.value).powi(2)
            }
            _ => 0.,
        }
    }

    pub(super) const fn body_contact_noise(&self) -> f64 {
        self.body_contact_noise
    }

    /// Evaluate the parasitics at the physical channel bias.
    /// # Errors
    /// Invalid physical bias or nonfinite constitutive output.
    pub fn evaluate(&self, bias: BsimSoiChannelBias) -> Result<BsimSoiParasiticPoint, ModelError> {
        self.evaluate_with_channel(bias, &self.drain.evaluate(bias)?)
    }

    /// Reuse an already evaluated channel point at the same bias and instance.
    /// # Errors
    /// Invalid thermal coordinate or nonfinite constitutive output.
    pub fn evaluate_with_channel(
        &self,
        bias: BsimSoiChannelBias,
        channel: &BsimSoiDrainChannelPoint,
    ) -> Result<BsimSoiParasiticPoint, ModelError> {
        let thermal = self.temperature.evaluate(bias.kelvin)?;
        // B4SOIload deliberately excludes bipolar and leakage dissipation.
        // Signed physical IDS times signed physical VDS is orientation invariant.
        let generated = if self.temperature.network().is_some() {
            channel.current * Jet::coordinate(bias.drain, 1, 1.)
        } else {
            Jet::constant(0.)
        };
        Ok(BsimSoiParasiticPoint {
            gate_electrode: if matches!(self.gate.mode, 1 | 3) {
                self.gate.electrode
            } else {
                0.
            },
            gate_relaxation: self
                .gate
                .relaxation(channel)
                .checked("gate relaxation conductance")?,
            body_contact: self.body_contact,
            drain_body: self.drain_body,
            source_body: self.source_body,
            heat: BsimSoiHeatPoint {
                generated: generated.checked("generated heat")?,
                residual: (Jet::thermal(thermal.conductive_heat) - generated)
                    .checked("thermal residual")?,
                energy: Jet::thermal(thermal.stored_heat),
            },
        })
    }
}

impl PreparedBsimSoiSetup {
    /// Bind the RF gate, body contact, distributed body and active thermal laws.
    /// # Errors
    /// Invalid instance, model or parasitic resistance geometry.
    pub fn prepare_parasitics(
        &self,
        index: usize,
        ambient: f64,
    ) -> Result<PreparedBsimSoiParasitics, ModelError> {
        let instance = self
            .instances
            .get(index)
            .ok_or(ModelError::MismatchedPreparedContext)?;
        let size = self
            .sizes
            .get(index)
            .ok_or(ModelError::MismatchedPreparedContext)?;
        let params = instance.parameters();
        let model = self.model.parameters();
        let geometry = size.geometry();
        let m = positive(real(params, "m")?, "parasitic multiplicity")?;
        let nf = real(params, "nf")?;
        let nseg = real(params, "nseg")?;
        let mode = integer(params, "rgatemod")?;
        let electrode = if mode == 0 {
            0.
        } else {
            let contacts = positive(real(model, "ngcon")?, "gate contact count")?;
            let resistance = real(model, "rshg")?
                * (real(model, "xgw")? + geometry.weff / nseg / 3. / contacts)
                / (contacts * nf * (real(params, "l")? - real(model, "xgl")?));
            m * if resistance > 0. {
                resistance.recip()
            } else {
                1e3
            }
        };
        let (body_contact, body_contact_noise) =
            if instance.topology().body_mode == BsimSoiBodyMode::Resistive {
                let rbody = real(model, "rbody")?;
                let halo = real(model, "rhalo")?;
                let key = super::super::native_size_key(instance)?;
                let mut owner = index;
                for (candidate, other) in self.instances[..index].iter().enumerate() {
                    if super::super::native_size_key(other)? == key {
                        owner = candidate;
                        break;
                    }
                }
                let cached = self.instances[owner].parameters();
                let internal = if rbody == 0. {
                    0.
                } else {
                    real(cached, "frbody")? * rbody * halo / halo.mul_add(geometry.leff, 2. * rbody)
                        * geometry.weff
                        / real(cached, "nseg")?
                        / nf
                };
                let external = real(params, "nrb")? * real(model, "rbsh")?;
                let resistance = if internal < 1e-3 {
                    external.max(1e-3)
                } else {
                    internal + external
                };
                let physical = m / positive(resistance, "body contact resistance")?;
                let raw = internal + external;
                (physical, if raw > 0. { m / raw } else { physical })
            } else {
                (0., 0.)
            };
        let body = |name| -> Result<f64, ModelError> {
            if integer(params, "rbodymod")? == 0 {
                return Ok(0.);
            }
            let resistance = real(params, name)?;
            Ok(m * if resistance < 1e-3 {
                1e3
            } else {
                real(model, "gbmin")? + resistance.recip()
            })
        };
        let gate = GateLaw {
            mode,
            electrode,
            xrcrg1: binned(size, "xrcrg1")?,
            beta_scale: binned(size, "xrcrg2")? * K_OVER_Q * ambient,
        };
        Ok(PreparedBsimSoiParasitics {
            drain: self.prepare_drain_channel(index, ambient)?,
            temperature: self.prepare_temperature(index, ambient)?,
            gate,
            body_contact,
            body_contact_noise,
            drain_body: body("rbdb")?,
            source_body: body("rbsb")?,
        })
    }
}
